using System;
using System.Linq;
using System.Reflection;
using Newtonsoft.Json.Linq;
using UnityEngine;
namespace CastleFight {
public static class Centaur030Scenarios {
    public static JArray Run(JObject catalog,JObject human,Action<bool,string> check){
        var rows=new JArray();HumanMatch m=null;
        void C(bool ok,string text){check(ok,text);rows.Add(new JObject{["ok"]=ok,["name"]=text});}
        void Call(string name,params object[] args)=>typeof(HumanMatch).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(m,args);
        void Reset(){m=new HumanMatch((JObject)catalog.DeepClone(),10000,1,-1,-1,(JObject)human.DeepClone());typeof(HumanMatch).GetField("botAge",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(m,100000f);}
        HumanMatch.Unit U(string raw,int team=0,Vector2? at=null){var u=m.Spawn(team,Array.FindIndex(m.Lines,l=>l.unit==raw),at??new Vector2(-40,0));u.onRoad=true;return u;}
        HumanMatch.Unit D(Vector2? at=null){var u=U("hfoo",1,at??new Vector2(-37,0));u.hp=u.maxHp=10000;u.armor=0;u.castPause=100000;return u;}
        void Hit(HumanMatch.Unit source,HumanMatch.Unit target){var weapon=m.Lines[source.kind].weapons[0];source.shotDamage=weapon.damage;Call("ResolveAttack",source.id,source.team,target.id,weapon.damage,weapon,0f,true);}
        Reset();foreach(var line in m.Lines.Where(l=>(l.unit??"").StartsWith("cU")))C(HumanMatch.Strings(line.stats["abilities"]).Any(id=>id!="CT01"),"Fighter has a real individual skill beyond Charge: "+line.unit);
        Reset();var spear=U("cU01");var target=D();for(int i=0;i<3;i++)Hit(spear,target);C(m.CentaurThrusts==0,"Spear thrust does not trigger before four successful hits");float before=target.hp;Hit(spear,target);C(m.CentaurThrusts==1&&Mathf.Abs(before-target.hp-42)<.01f,"Fourth basic spear hit deals its real 28 plus 14 weapon bonus");
        Reset();spear=U("cU11");target=D();for(int i=0;i<4;i++)Hit(spear,target);C(m.CentaurThrusts==1&&Mathf.Abs(target.maxHp-target.hp-282)<.01f,"Veteran spear adds seventy percent on its fourth hit");
        Reset();spear=U("cU01");for(int i=0;i<3;i++){target=D();target.hp=1;Hit(spear,target);}target=D();before=target.hp;Hit(spear,target);C(m.CentaurThrusts==1&&Mathf.Abs(before-target.hp-42)<.01f,"Killing blows advance the personal hit counter without hitting defeated targets twice");
        Reset();var guard=U("cU02");before=guard.hp;m.DamageUnit(guard,100,1,"chaos",spell:false,ignoreArmor:true);C(Mathf.Abs(before-guard.hp-93)<.01f,"Guard blocks seven physical damage after armor");before=guard.hp;m.DamageUnit(guard,100,1,"chaos",spell:true,ignoreArmor:true);C(Mathf.Abs(before-guard.hp-100)<.01f,"Guard cannot block spell damage");before=guard.hp;m.DamageUnit(guard,.4f,1,"chaos",spell:false,ignoreArmor:true);C(Mathf.Abs(before-guard.hp-.4f)<.01f,"Guard never increases an incoming hit smaller than one");
        Reset();guard=U("cU12");before=guard.hp;m.DamageUnit(guard,100,1,"chaos",spell:false,ignoreArmor:true);C(Mathf.Abs(before-guard.hp-88)<.01f,"Iron guard uses its stronger twelve-point physical block");
        Reset();var thrower=U("cU03");target=D();target.spellResist=1;Hit(thrower,target);Hit(thrower,target);C(!target.effects.Any(e=>e.id=="CT21"),"Axe armor break waits for three real hits");Hit(thrower,target);C(m.CentaurBreaks==1&&m.Stat(target,"armor")==-2,"Third axe hit cracks armor through magic immunity");
        var master=U("cU13");for(int i=0;i<3;i++)Hit(master,target);C(m.Stat(target,"armor")==-4&&target.effects.Count(e=>e.group=="centaur_armor_break")==1,"Master break replaces the weaker field and does not stack");for(int i=0;i<3;i++)Hit(thrower,target);C(m.Stat(target,"armor")==-4,"Weaker axe cannot overwrite a stronger active break");Call("TickEffects",target,5.1f);C(m.Stat(target,"armor")==0,"Armor break expires without permanently altering base armor");
        Reset();var witch=U("cU05");target=D();var neighbor=D(target.position+Vector2.right*4);var far=D(target.position+Vector2.right*7);var ally=U("cU01",0,target.position);var immune=D(target.position);immune.spellResist=1;var flying=U("h016",1,target.position);float mana=witch.mana;Call("TickCentaur",.25f);C(m.CentaurNeedles==1&&witch.mana==mana-25&&target.hp==9940&&neighbor.hp==9940,"Witch pays mana and damages the actual ground area with sand needles");C(far.hp==10000&&ally.hp==ally.maxHp&&immune.hp==10000&&flying.hp==flying.maxHp,"Sand needles exclude outside range, allies, immunity and air");Call("TickCentaur",.3f);C(m.CentaurNeedles==1,"Sand needles cannot bypass their eight-second cooldown");
        Reset();witch=U("cU15");target=D();Call("TickCentaur",.25f);C(target.hp==9880,"Seer has the stronger one-hundred-twenty damage needles");
        Reset();witch=U("cU05");target=D();m.VisionTest=(team,p)=>false;Call("TickCentaur",.25f);C(m.CentaurNeedles==0&&witch.mana==100,"Hidden enemies do not consume needle mana or cooldown");
        Reset();witch=U("cU05");target=D();witch.stun=1;Call("TickCentaur",.25f);C(m.CentaurNeedles==0,"Stunned witch cannot cast new spells");
        Reset();witch=U("cU05");target=D();witch.effects.Add(new HumanMatch.Effect{id="qa_silence",left=3,config=new JObject{["silence"]=true}});Call("TickCentaur",.25f);C(m.CentaurNeedles==0&&m.CentaurCasts==0&&witch.mana==100,"Silence blocks both sand spells without consuming mana");
        Reset();witch=U("cU05");target=D();witch.strikeLeft=.2f;Call("TickCentaur",.25f);C(m.CentaurNeedles==0,"Instant spell waits for a pending weapon release");
        Reset();var drum=U("cU06");var wounded=Enumerable.Range(0,5).Select(i=>U("cU01",0,new Vector2(-39,i))).ToArray();for(int i=0;i<5;i++)wounded[i].hp=100+i;target=D();target.hp=100;mana=drum.mana;Call("TickCentaur",.25f);C(m.CentaurRallies==1&&drum.mana==mana-30&&wounded.Take(4).All(u=>u.hp==135+Array.IndexOf(wounded,u))&&wounded[4].hp==104,"Drummer heals exactly the four most wounded allies by thirty-five");C(target.hp==100,"Drummer cannot heal enemy fighters");Call("TickCentaur",.3f);C(m.CentaurRallies==1,"Drummer healing respects its cooldown");
        Reset();drum=U("cU16");var injured=U("cU01",0,new Vector2(-39,0));injured.hp=100;Call("TickCentaur",.25f);C(injured.hp==170,"Senior drummer restores seventy HP");
        Reset();drum=U("cU06");mana=drum.mana;Call("TickCentaur",.25f);C(drum.mana==mana&&m.CentaurRallies==0,"Full-health army does not waste healer mana");
        Reset();var siege=U("cU07");target=D();neighbor=D(target.position+Vector2.right*3);ally=U("cU01",0,target.position);flying=U("h016",1,target.position);Hit(siege,target);C(neighbor.hp<10000&&ally.hp==ally.maxHp&&flying.hp==flying.maxHp,"Destroyer cleave hits another ground enemy and excludes allies and flyers");
        Reset();var khan=U("cU0A");target=D();var hero=U("cU0A",1,new Vector2(-37,1));hero.castPause=100000;immune=D(new Vector2(-37,2));immune.spellResist=1;flying=U("h016",1,new Vector2(-37,2));Call("TickCentaur",.25f);C(m.CentaurStomps==1&&target.hp==9910&&target.stun==1&&hero.stun==.5f,"Khan stomps in ordinary combat without needing a charge, with shortened hero stun");C(immune.hp==10000&&immune.stun==0&&flying.hp==flying.maxHp&&flying.stun==0,"Khan stomp respects air and immunity");Call("TickCentaur",.3f);C(m.CentaurStomps==1,"Khan cannot spam the stomp during its ten-second cooldown");
        Reset();khan=U("cU0A");hero=U("cU0A",1,new Vector2(-37,1));Call("TickCentaur",.25f);C(m.CentaurStomps==1&&hero.stun==.5f&&khan.stun==0,"A Khan stunned earlier in the same spell batch cannot cast back immediately");
        Reset();witch=U("cU05");drum=U("cU06");injured=U("cU01");injured.hp=100;khan=U("cU0A");target=D();m.NetworkReplica=true;Call("TickCentaur",.25f);C(m.CentaurNeedles+m.CentaurRallies+m.CentaurStomps==0,"Replica cannot execute new centaur ability authority");m.NetworkReplica=false;m.Winner=1;Call("TickCentaur",.25f);C(m.CentaurNeedles+m.CentaurRallies+m.CentaurStomps==0,"Finished match cannot execute new centaur ability authority");
        // Retain the original race identity after adding sustained-combat skills.
        Reset();spear=U("cU01");for(int i=0;i<62;i++)m.TickUnit(spear,.05f);C(m.CentaurChargeProgress(spear)>=1,"The original charge still fills during actual movement");Call("BeginAttack",spear,m.Lines[spear.kind].weapons[0],-1);C(Mathf.Abs(spear.shotDamage-39.2f)<.01f,"Original charge still grants its forty-percent opening bonus");
        Reset();khan=U("cU0A");for(int i=0;i<62;i++)m.TickUnit(khan,.05f);target=D(khan.position+Vector2.right*5.5f);var escort=U("cU01",0,khan.position+Vector2.up*3);escort.castPause=100000;Call("TickCentaur",.25f);C(m.CentaurStomps==0&&m.CentaurChargeProgress(khan)>=1,"Ready Khan charge takes priority over stomp and cannot be cancelled by its cast pause");
        for(int i=0;i<50;i++)m.Step(.05f);C(m.CentaurCharges==1&&escort.effects.Any(e=>e.id=="CT10")&&m.CentaurStomps==1,"Actual combat releases the Khan charge and ally cry before using its independent stomp");
        return rows;
    }
}
}
